# Secure File Sharing Website

I'll build this with **Node.js + Express** on the server (password checked server-side, hashed with bcrypt) and a simple HTML/JS frontend. Downloads go through a server endpoint that validates the password before streaming the file — there's no direct URL to the file.

## Project structure

```
file-share/
├── package.json
├── server.js
├── public/
│   ├── upload.html
│   └── download.html
└── uploads/           (created automatically, NOT served statically)
```

## `package.json`

```json
{
  "name": "file-share",
  "version": "1.0.0",
  "type": "commonjs",
  "scripts": { "start": "node server.js" },
  "dependencies": {
    "bcrypt": "^5.1.1",
    "express": "^4.19.2",
    "multer": "^1.4.5-lts.1",
    "nanoid": "^3.3.7"
  }
}
```

Install with:

```bash
npm install
```

## `server.js`

```js
const express = require('express');
const multer = require('multer');
const bcrypt = require('bcrypt');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { nanoid } = require('nanoid');

const app = express();
const PORT = process.env.PORT || 3000;

const UPLOAD_DIR = path.join(__dirname, 'uploads');
const DB_FILE = path.join(__dirname, 'files.json');

// Ensure uploads dir + DB exist
fs.mkdirSync(UPLOAD_DIR, { recursive: true });
if (!fs.existsSync(DB_FILE)) fs.writeFileSync(DB_FILE, '{}');

// --- Tiny JSON "database" ---
function readDb() {
  return JSON.parse(fs.readFileSync(DB_FILE, 'utf8'));
}
function writeDb(db) {
  fs.writeFileSync(DB_FILE, JSON.stringify(db, null, 2));
}

// --- Multer: store file under a random internal name, no original-name leak ---
const storage = multer.diskStorage({
  destination: (req, file, cb) => cb(null, UPLOAD_DIR),
  filename: (req, file, cb) => cb(null, crypto.randomBytes(24).toString('hex')),
});
const upload = multer({
  storage,
  limits: { fileSize: 200 * 1024 * 1024 }, // 200 MB
});

app.use(express.urlencoded({ extended: true }));
app.use(express.json());
app.use(express.static('public'));       // serves ONLY the HTML pages under /public
// NOTE: uploads/ is deliberately NOT in the static root -> no direct URLs

// --- Upload endpoint ---
app.post('/api/upload', upload.single('file'), async (req, res) => {
  try {
    if (!req.file) return res.status(400).json({ error: 'No file uploaded' });
    const { password } = req.body;
    if (!password || password.length < 4) {
      fs.unlinkSync(req.file.path);
      return res.status(400).json({ error: 'Password must be at least 4 characters' });
    }

    const passwordHash = await bcrypt.hash(password, 12);
    const id = nanoid(12);

    const db = readDb();
    db[id] = {
      storedName: req.file.filename,
      originalName: req.file.originalname,
      mimeType: req.file.mimetype,
      size: req.file.size,
      passwordHash,
      createdAt: new Date().toISOString(),
    };
    writeDb(db);

    res.json({ id, link: `/download.html?id=${id}` });
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Upload failed' });
  }
});

// --- Metadata endpoint (used by the download page to show the filename) ---
app.get('/api/info/:id', (req, res) => {
  const db = readDb();
  const entry = db[req.params.id];
  if (!entry) return res.status(404).json({ error: 'Not found' });
  res.json({
    originalName: entry.originalName,
    size: entry.size,
    createdAt: entry.createdAt,
  });
});

// --- Download endpoint: ONLY way to get the bytes, password-checked ---
app.post('/api/download/:id', async (req, res) => {
  const db = readDb();
  const entry = db[req.params.id];
  if (!entry) return res.status(404).send('Not found');

  const { password } = req.body;
  if (!password) return res.status(400).send('Password required');

  const ok = await bcrypt.compare(password, entry.passwordHash);
  if (!ok) return res.status(401).send('Wrong password');

  const filePath = path.join(UPLOAD_DIR, entry.storedName);
  if (!fs.existsSync(filePath)) return res.status(410).send('File missing');

  res.setHeader(
    'Content-Disposition',
    `attachment; filename="${entry.originalName.replace(/"/g, '')}"`
  );
  res.setHeader('Content-Type', entry.mimeType || 'application/octet-stream');
  res.setHeader('Content-Length', entry.size);
  res.setHeader('Cache-Control', 'no-store');

  fs.createReadStream(filePath).pipe(res);
});

app.listen(PORT, () => console.log(`Listening on http://localhost:${PORT}`));
```

## `public/upload.html`

```html
<!doctype html>
<html>
<head>
  <meta charset="utf-8" />
  <title>Upload a file</title>
  <style>
    body { font-family: system-ui, sans-serif; max-width: 520px; margin: 3rem auto; padding: 0 1rem; }
    input, button { display: block; width: 100%; padding: .6rem; margin: .5rem 0; font-size: 1rem; }
    #result { margin-top: 1rem; padding: 1rem; background: #eef; border-radius: 6px; display: none; word-break: break-all; }
    code { background: #ddd; padding: .1rem .3rem; border-radius: 3px; }
  </style>
</head>
<body>
  <h1>Share a file</h1>
  <form id="form">
    <input type="file" name="file" required />
    <input type="password" name="password" placeholder="Choose a password" required minlength="4" />
    <button type="submit">Upload</button>
  </form>
  <div id="result"></div>

  <script>
    const form = document.getElementById('form');
    const result = document.getElementById('result');

    form.addEventListener('submit', async (e) => {
      e.preventDefault();
      result.style.display = 'none';
      result.textContent = 'Uploading…';

      const fd = new FormData(form);
      const res = await fetch('/api/upload', { method: 'POST', body: fd });
      const data = await res.json();

      if (!res.ok) {
        result.style.display = 'block';
        result.textContent = 'Error: ' + (data.error || 'unknown');
        return;
      }

      const fullLink = location.origin + data.link;
      result.style.display = 'block';
      result.innerHTML =
        'Share this link:<br><code>' + fullLink + '</code><br>' +
        '<small>Tell your friends the password out of band.</small>';
      form.reset();
    });
  </script>
</body>
</html>
```

## `public/download.html`

```html
<!doctype html>
<html>
<head>
  <meta charset="utf-8" />
  <title>Download file</title>
  <style>
    body { font-family: system-ui, sans-serif; max-width: 520px; margin: 3rem auto; padding: 0 1rem; }
    input, button { display: block; width: 100%; padding: .6rem; margin: .5rem 0; font-size: 1rem; }
    #msg { margin-top: 1rem; }
    .err { color: #b00; }
  </style>
</head>
<body>
  <h1>Download file</h1>
  <p id="filename">Loading…</p>
  <form id="form">
    <input type="password" id="password" placeholder="Enter password" required autofocus />
    <button type="submit">Unlock &amp; download</button>
  </form>
  <div id="msg"></div>

  <script>
    const id = new URLSearchParams(location.search).get('id');
    const form = document.getElementById('form');
    const msg = document.getElementById('msg');
    const filename = document.getElementById('filename');

    if (!id) {
      filename.textContent = 'Missing file id.';
      form.style.display = 'none';
    } else {
      fetch('/api/info/' + encodeURIComponent(id))
        .then(r => r.ok ? r.json() : Promise.reject())
        .then(info => { filename.textContent = 'File: ' + info.originalName; })
        .catch(() => { filename.textContent = 'File not found.'; form.style.display = 'none'; });
    }

    form.addEventListener('submit', async (e) => {
      e.preventDefault();
      msg.className = '';
      msg.textContent = 'Checking password…';

      const res = await fetch('/api/download/' + encodeURIComponent(id), {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: 'password=' + encodeURIComponent(document.getElementById('password').value),
      });

      if (!res.ok) {
        msg.className = 'err';
        msg.textContent = res.status === 401 ? 'Wrong password.' : ('Error ' + res.status);
        return;
      }

      // Success: convert the streamed response into a downloaded file
      const blob = await res.blob();
      const cd = res.headers.get('Content-Disposition') || '';
      const match = /filename="([^"]+)"/.exec(cd);
      const name = match ? match[1] : 'download';

      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url; a.download = name;
      document.body.appendChild(a); a.click(); a.remove();
      URL.revokeObjectURL(url);

      msg.textContent = 'Downloaded.';
    });
  </script>
</body>
</html>
```

## How the security requirements are met

| Requirement | How it's handled |
|---|---|
| Password stored hashed | `bcrypt.hash(password, 12)` before saving; only the hash is written to `files.json`. |
| Password checked on the server only | The browser never sees or compares any hash/password. It POSTs the typed password; `bcrypt.compare` runs on the server. |
| No direct URL to the file | Files are stored under a random hex name in `uploads/`, which is **outside** the `express.static('public')` root. The only way to read bytes is `POST /api/download/:id` after a successful password check. |
| Can't guess the file URL | The share `id` is a `nanoid(12)` (≈ 71 bits of randomness); the internal filename is 24 random bytes. |

## Run it

```bash
npm install
node server.js
```

Then open `http://localhost:3000/upload.html`, upload a file with a password, copy the link, and share it along with the password (send the password via a different channel — e.g., Signal/SMS — so it isn't leaked alongside the link).

## Optional production hardening

- Put it behind HTTPS (`nginx` / Caddy) — passwords are sent in plaintext over HTTP otherwise.
- Add a small delay or rate-limit on `/api/download/:id` to slow brute-force attempts.
- Use a real database and object storage (S3) for scale.
- Add an expiry timestamp per file and a cleanup cron.
- If you ever serve `uploads/` over a CDN or static server, be sure **not** to — that would break requirement #3.

